const fs = require("fs");
const { setTimeout: sleep } = require("timers/promises");

async function main() {
  console.log("1. bắt đầu");

  await sleep(50);                       // chờ 50ms mà không chặn
  fs.writeFileSync("/n.txt", "42");
  const text = await fs.promises.readFile("/n.txt", "utf8");
  console.log("2. đọc được", text);

  try {
    await fs.promises.readFile("/khong-co.txt");
  } catch (err) {
    console.log("3. lỗi:", err.code);    // ENOENT
  }
}

main();
